      "type": "Text",
      "props": {
        "text": "- **Router:** Netgear Nighthawk R7000"
      },
      "children": []
    },
    "diagnostic_context_item_2": {
      "type": "Text",
      "props": {
        "text": "- **ISP:** Comcast"
      },
      "children": []
    },
    "diagnostic_context_item_3": {
      "type": "Text",
      "props": {
        "text": "- **Symptom:** Hourly internet disconnects for ~5 minutes; router's internet light turns amber."
      },
      "children": []
    },
    "diagnostic_context_item_4": {
      "type": "Text",
      "props": {
        "text": "- **Initial Steps Taken:** Rebooting modem/router and checking physical cables."
      },
      "children": []
    },
    "guide_title": {
      "type": "Text",
      "props": {
        "text": "Step-by-Step Diagnostic Guide",
        "variant": "h2"
      },
      "children": []
    },
    "guide_intro": {
      "type": "Text",
      "props": {
        "text": "Follow these steps in order. After each step, monitor your connection for at least an hour to see if the issue is resolved before proceeding to the next."
      },
      "children": []
    },
