      "type": "Text",
      "props": {
        "text": "Step 1: Check Router Logs for Clues",
        "variant": "h3"
      },
      "children": []
    },
    "step_1_body_1": {
      "type": "Text",
      "props": {
        "text": "The router's system logs often contain specific error messages that coincide with the disconnects. Look for entries like \"[DoS attack: ...]\", \"[Internet disconnected]\", or \"[DHCP IP renewal failed]\". This will give you a strong clue."
      },
      "children": []
    },
    "step_1_body_2": {
      "type": "Text",
      "props": {
        "text": "How to access: Open a web browser and navigate to routerlogin.net or 192.168.1.1. Log in with your credentials (default is admin/password). The logs are usually under an 'Advanced' > 'Administration' > 'Logs' section."
      },
      "children": []
    },
    "step_1_button": {
      "type": "Button",
      "props": {
        "label": "Go to Router Login"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "http://routerlogin.net"
          }
        }
      }
    },
